        "genre": "narrative",
        "title": "La peça dins del vas",
        "summary": "La fotografia d’una batedora sembla assenyalar una pèrdua. Mirar el conjunt des d’un altre angle canvia la primera conclusió.",
        "paragraphs": [
          "A la biblioteca de les coses, un local veïnal que prestava objectes d’ús ocasional, acabaven de retornar una batedora de mà. La Rosa, l’adulta que coordinava el servei, l’havia deixada desendollada damunt un drap. La Noa i l’Adil, dos estudiants que hi col·laboraven, van acostar la fotografia del conjunt. La persona que havia portat la bossa ja se n’havia anat; encara ningú no li havia preguntat per cap peça.",
          "La imatge mostrava el cos de la batedora, les varetes metàl·liques, un vas mesurador alt i un adaptador blanc: la peça que unia les varetes al cos. L’Adil va anar assenyalant cada objecte damunt el drap. En arribar a l’adaptador es va aturar. «Aquest falta», va dir, i va escriure la paraula en un paper. Havia comptat tres objectes separats. El vas estava dret darrere les varetes, tal com la Rosa l’havia tret de la bossa.",
          "—Truquem abans que s’allunyi més? —va preguntar l’Adil.\nLa Noa va mirar la fotografia i després el vas. La part baixa era translúcida, però les ratlles de mesura i el reflex de la finestra feien difícil veure el fons.\n—Un moment. A dins no hem mirat.\nLa Rosa va agafar el vas i el va inclinar a poc a poc damunt el drap. Es va sentir un copet. L’adaptador estava encaixat de costat al fons; vist des de dalt, la vora blanca semblava pertànyer a la base.",
          "La Rosa va treure la peça i la va comparar amb la foto. Mentre l’examinava, amb l’aparell sempre desendollat, l’Adil va tornar a mirar el paper.\n—Doncs gairebé li dic que se l’ha deixada a casa.\n—Jo tampoc no la veia —va respondre la Noa—. M’ha estranyat que no es veiés el fons.\nEls estudiants es van quedar amb la fotografia i les notes. Va ser la Rosa qui va comprovar l’estat de les peces i va continuar la revisió de l’aparell.",
          "La foto antiga tenia un altre inconvenient: l’adaptador tocava el vas i les dues vores clares es confonien. La Noa va proposar fotografiar les peces separades. L’Adil va afegir que les podien deixar sempre en el mateix ordre en preparar la bossa. La Rosa els va demanar que fessin primer la foto; després ja veurien com desar-les sense que es colpegessin. Una imatge clara ajudaria, tot i que cada retorn continuaria necessitant una revisió.",
          "L’Adil va ratllar «falta» i va escriure a sota: «Adaptador trobat dins del vas». No va voler arrencar el paper: li servia per recordar per què havia canviat la nota. La Noa va posar la foto nova al costat de l’antiga. A la nova es podien comptar les peces sense endevinar on s’acabava l’una i començava l’altra. La van desar a la funda del conjunt quan la tinta va ser seca.",
          "La trucada va quedar sense fer. Abans d’anar-se’n, l’Adil va aixecar la motxilla per mirar a sota: tampoc no trobava l’estoig. La Noa va assenyalar la butxaca oberta d’un costat. Ell el va treure i va riure. Aquest cop no havia arribat a escriure res."
        ],
