          "La biblioteca de las cosas instaló este sábado una parada en el mercado para darse a conocer. El servicio funciona en un local vecinal y presta objetos de uso ocasional. Rosa, su coordinadora, acudió con Noa y Adil, dos estudiantes colaboradores. Habían colocado un proyector en el centro de la mesa, junto a unas fotografías de otros objetos.",
          "Noa esperaba muchas preguntas sobre películas en casa. Sin embargo, las primeras personas se interesaron por un carro plegable que estaba debajo de la mesa. El equipo lo había usado para llevar los folletos. «¿Ese también se presta?», preguntó una mujer con dos bolsas llenas. Después quiso saber cuánto ocupaba al doblarlo y dónde estaba el local.",
