          "Las preguntas cambiaron la parada. Dejaron el proyector a un lado y pusieron el carro abierto delante de la mesa, sin tapar el paso. Adil colocó dentro una caja vacía para mostrar el espacio de carga. También acercaron un pequeño mapa del camino al local. Varias personas habían dicho que pasaban por aquella calle sin saber qué había dentro.",
