        "title": "La parada cambió de centro",
        "summary": "La biblioteca cambia su parada tras escuchar al público. La crónica distingue lo que permiten saber las conversaciones y lo que aún queda abierto.",
        "paragraphs": [
          "La biblioteca de las cosas se presentó este sábado en el mercado con una parada informativa. El servicio presta objetos de uso ocasional desde un local de la asociación vecinal. Rosa, la adulta que lo coordina, acudió con Noa y Adil, dos estudiantes colaboradores. Llevaron un proyector, fotografías de otros objetos y folletos con un mapa del local. La visita pretendía llegar a quienes conocían aquella calle, pero pasaban de largo. Esta crónica del boletín vecinal combina la observación de la mañana con los comentarios del equipo al recoger.",
          "El proyector comenzó en el centro de la mesa, dirigido hacia el pasillo del mercado. Estaba apagado: se había llevado para mostrarlo, no para proyectar. «Yo tenía preparada la explicación de cómo pedirlo para una fiesta», contó Noa más tarde. Esperaba que fuera el gran reclamo. Sin embargo, las primeras preguntas se dirigieron al carro plegable que el equipo había usado para transportar los papeles. Lo habían guardado debajo de la mesa, con los folletos sobrantes dentro.",
          "Una mujer que llevaba dos bolsas llenas se agachó para señalarlo. Preguntó si se prestaba, cuánto ocupaba cerrado y por dónde podía llegar andando al local. Rosa lo sacó y señaló las partes que se doblaban. Otro visitante preguntó el precio de compra. Ella explicó que los objetos se llevaban durante un tiempo y debían regresar al local. Aquel carro estaba ocupado por el propio equipo durante la mañana; para usarlo otro día habría que consultar si estaba libre.",
          "Después de varias conversaciones parecidas, Adil propuso cambiar la disposición. Sacaron los papeles, abrieron el carro delante de la mesa, fuera del paso, y colocaron una caja vacía dentro. Así se veía su capacidad sin que nadie tuviera que agacharse. El proyector quedó en un lateral, todavía a la vista. Acercaron también el mapa al borde: algunos visitantes reconocían la calle, pero necesitaban una referencia para encontrar la puerta. Noa empezó a señalar el camino antes de explicar los objetos.",
          "El cambio no dejó al proyector sin público. Una familia preguntó por él para una fiesta; dos vecinos se interesaron por la fotografía de una máquina de coser. El carro había permitido iniciar otras conversaciones, especialmente entre personas que ya llevaban compras. «Lo trajimos para cargar los papeles y acabamos sacándolo en casi todas las charlas», recordó Adil. Su impresión describe aquella mañana; el equipo no había preguntado por los mismos objetos a todas las personas que pasaban.",
          "En total anotaron dieciocho conversaciones. Quedaron fuera del recuento quienes solo miraron o cogieron un folleto. La parada informaba; los objetos se entregaban en el local, donde se preparaban los préstamos. Por eso, la cifra de charlas no permite calcular cuántos préstamos habrá ni convertir al carro en el objeto preferido de todo el barrio. Además, quienes no fueron al mercado o no se detuvieron no aparecen en estas notas. Rosa conservó las preguntas repetidas para mejorar la explicación del servicio.",
          "Antes de cerrar, revisaron el folleto que habían repartido. Tenía una fotografía grande del proyector y el mapa en un rincón pequeño. Noa señaló que le había costado enseñarlo sin taparlo con los dedos. Rosa propuso ampliar el mapa y añadir una imagen del carro plegado. Prepararían una prueba para la siguiente visita, prevista para el mes siguiente y aún sin fecha concreta.",
          "Al regresar, el carro volvió a llevar los folletos y la caja vacía. El proyector viajó en su funda. Esta vez habían guardado el mapa encima de todo."
        ],
